BEGIN;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.curriculum_versions v JOIN public.curriculum_subjects s ON s.id = v.subject_id WHERE s.code = 'TR' AND v.version_code = 'TYMM-2024-TR' AND v.status = 'draft') THEN RAISE EXCEPTION 'Türkçe taslak sürüm bulunamadı; aktarım durduruldu'; END IF; IF EXISTS (SELECT 1 FROM public.curriculum_grades g JOIN public.curriculum_versions v ON v.id = g.version_id JOIN public.curriculum_subjects s ON s.id = v.subject_id WHERE s.code = 'TR' AND v.version_code = 'TYMM-2024-TR' AND g.grade = 8) THEN RAISE EXCEPTION '8. sınıf zaten var; aktarım durduruldu'; END IF; END $$;
COMMIT;
